#' Run GeneCycle rhythmicity detection
#'
#' @param inputs Inputs for rhythmicity detection function generated by
#'   `prepare_genecycle()`
#' @param grp Group that is analysed
#' @param method_args, Additional parameters passed to
#'   `GeneCycle::robust.spectrum()` and `GeneCycle::robust.g.test()`
#' @param missing_data_fraction Fraction of missing data in the dataset.
#'
#' @importFrom GeneCycle robust.spectrum robust.g.test
#'
#' @returns A data frame
execute_genecycle <- function(
  inputs,
  grp,
  method_args = list(),
  missing_data_fraction = 0
) {
  # TODO: In the main clockworks function, inform the user that if they want to
  # run 'rank' GeneCycle with an unknown period they should set `index = NA` in
  # method_args. If they want to run 'regression' GeneCycle with an unknown
  # period, they should set `periodicity.time = FALSE`, otherwise the enetered
  # period will be used. I guess it would also be important to mention that in
  # this case, whatever is defined as `period` in `clockworks()` will be
  # ignored for GeneCycle.

  # Handle missing data ----
  feature_order <- colnames(inputs$spectrum$x)
  invalid_features <- character(0)
  if (missing_data_fraction > 0) {
    dat <- inputs$spectrum$x
    cols_no_consecutive <- apply(dat, 2, function(x) {
      idx <- which(!is.na(x))
      !any(diff(idx) == 1)
    })
    invalid_features <- colnames(dat)[cols_no_consecutive]

    if (length(invalid_features) > 0) {
      warning(
        "The features listed below will be excluded because they have no consecutive non-NA values.\n - ",
        paste(invalid_features, collapse = "\n - "),
        call. = FALSE
      )
      # Remove invalid features from the input data frame
      inputs$spectrum$x <- dat[, !colnames(dat) %in% invalid_features]
    }
  }

  # Combine method_args with user input ----
  # Get list of possible arguments for the two functions
  spectrum_argnames <- formalArgs(GeneCycle::robust.spectrum)
  gtest_argnames <- formalArgs(GeneCycle::robust.g.test)

  # Get user input
  spectrum_user_args <- method_args[intersect(
    spectrum_argnames,
    names(method_args)
  )]
  gtest_user_args <- method_args[intersect(gtest_argnames, names(method_args))]

  # Overwrite default inputs with user inputs
  spectrum_inputs <- utils::modifyList(inputs$spectrum, spectrum_user_args)
  gtest_inputs <- utils::modifyList(inputs$gtest, gtest_user_args)

  # If user set 'index = NA' remove it (NA or NULL do not work, index just needs
  # to be missing for expected behaviour). It is also not set at all if no
  # period is defined or the number of cycles is unknown.
  if (isTRUE(is.na(gtest_inputs$index))) {
    gtest_inputs$index <- NULL
  }

  # Determine how to run analysis ----
  algorithm <- spectrum_inputs$algorithm # Note: Could also be gtest_inputs$algorithm
  if (algorithm == "regression") {
    gtest_inputs$perm <- TRUE
  }
  approach <- ifelse(gtest_inputs$perm == TRUE, "permutation", "montecarlo")
  known_period <- switch(
    algorithm,
    rank = ifelse("index" %in% names(gtest_inputs), TRUE, FALSE),
    regression = ifelse(spectrum_inputs$periodicity.time == FALSE, FALSE, TRUE),
    stop("'algorithm' must be 'rank' or 'regression'.")
  )

  # Handle constant features ----
  # Note: These features need to be removed for the rank-based permutation approach
  constant_features <- character(0)
  if (algorithm == "rank" && approach == "permutation") {
    dat <- spectrum_inputs$x
    cols_constant <- apply(dat, 2, function(x) {
      x_obs <- x[!is.na(x)]
      length(x_obs) == 0 || sd(x_obs) == 0
    })
    constant_features <- colnames(dat)[cols_constant]

    if (length(constant_features) > 0) {
      warning(
        "The rank-based algorithm of GeneCycle cannot handle constant time-series when using the ",
        "permutation-based approach. The features listed below are constant and will therefore be ",
        "excluded from the analysis and assigned a p-value of 1.\n - ",
        paste(constant_features, collapse = "\n - "),
        call. = FALSE
      )
      spectrum_inputs$x <- dat[,
        !colnames(dat) %in% constant_features,
        drop = FALSE
      ]
    }
  }

  # Run analysis ----
  # Note: Whether the period is known or not for rank-based approach is
  # determined by the existence or absence of gtest_inputs$index, so no if
  # statement is necessary. For the regression-based approach it's a bit more
  # complicated, however it's easier in the sense that the Monte Carlo approach
  # is not available, only permutation.
  if (algorithm == "rank" && approach == "montecarlo") {
    y <- do.call(GeneCycle::robust.spectrum, spectrum_inputs)
    gtest_inputs$y <- y
    pvals <- do.call(GeneCycle::robust.g.test, gtest_inputs)

    # Delete file created by robust.spectrum()
    unlink(paste0("g_pop_length_", nrow(y), ".txt"))
    unlink(paste0("g_pop_length_", nrow(y), "indexed.txt"))
  } else if (algorithm == "rank" && approach == "permutation") {
    y <- do.call(GeneCycle::robust.spectrum, spectrum_inputs)
    gtest_inputs$y <- y
    gtest_inputs$x <- spectrum_inputs$x

    # Temporarily replace GeneCycle's internal spearman() function to
    # avoid NA values when some expression values are identical
    old_spearman <- get("spearman", envir = asNamespace("GeneCycle"))
    assignInNamespace("spearman", safe_spearman, ns = "GeneCycle")
    on.exit(
      assignInNamespace("spearman", old_spearman, ns = "GeneCycle"),
      add = TRUE
    )

    pvals <- do.call(GeneCycle::robust.g.test, gtest_inputs)
  } else if (algorithm == "regression" && known_period == FALSE) {
    y <- do.call(GeneCycle::robust.spectrum, spectrum_inputs)
    gtest_inputs$y <- y
    gtest_inputs$x <- spectrum_inputs$x
    pvals <- do.call(GeneCycle::robust.g.test, gtest_inputs)
  } else if (algorithm == "regression" && known_period == TRUE) {
    # In this (and only this) case, `robust.spectrum` returns p-values.
    pvals <- do.call(GeneCycle::robust.spectrum, spectrum_inputs)
  }

  # Period estimates ----
  n_rows <- nrow(spectrum_inputs$x)
  delta_t <- inputs$delta_t
  if (is.null(delta_t)) delta_t <- NA
  if (algorithm == "regression" && known_period == TRUE) {
    # The given period is fitted exactly
    period_est <- rep(spectrum_inputs$periodicity.time, ncol(spectrum_inputs$x))
  } else if (algorithm == "rank" && known_period == TRUE) {
    # Only the period of the selected index is tested
    period_tested <- genecycle_index_period(
      gtest_inputs$index,
      n_rows,
      delta_t,
      algorithm
    )
    period_est <- rep(period_tested, ncol(spectrum_inputs$x))
    requested <- inputs$spectrum$periodicity.time
    if (!isFALSE(requested)) {
      warn_tested_periods(
        "GeneCycle (rank-based algorithm)",
        requested = requested,
        tested = period_tested,
        rule = paste0(
          "2 * duration / k, with duration = number of time points * ",
          "delta_t (here ", n_rows * delta_t, ") and k a whole number"
        ),
        note = paste0(
          "The tested period (index = ", gtest_inputs$index, ") is reported ",
          "as 'period_estimate'."
        )
      )
    }
  } else {
    # No period given: the period of the highest peak of the spectrum, which
    # is the peak used by the g-statistic
    rows <- if (algorithm == "regression" && n_rows %% 2 == 0) {
      seq(2, nrow(y) - 1)
    } else {
      seq(2, nrow(y))
    }
    peak_idx <- apply(y[rows, , drop = FALSE], 2, function(v) {
      if (all(is.na(v)) || max(v, na.rm = TRUE) <= 0) {
        return(NA_integer_)
      }
      which.max(v)
    })
    period_est <- genecycle_index_period(
      rows[peak_idx],
      n_rows,
      delta_t,
      algorithm
    )
  }

  # Add feature IDs and group to results df (if not there already)
  df_res <- data.frame(
    feature = colnames(spectrum_inputs$x),
    group = grp,
    period_estimate = as.numeric(period_est),
    pval = as.numeric(pvals)
  )

  # Add exluded features back to results with NA values
  if (length(invalid_features) > 0) {
    missing_rows <- data.frame(
      feature = invalid_features,
      group = grp,
      period_estimate = NA,
      pval = NA
    )
    df_res <- rbind(df_res, missing_rows)
    df_res <- df_res[order(match(df_res$feature, feature_order)), ]
    rownames(df_res) <- as.character(seq_len(nrow(df_res)))
  }

  # Add constant features back to results with p-value of NA
  if (length(constant_features) > 0) {
    missing_rows <- data.frame(
      feature = constant_features,
      group = grp,
      period_estimate = NA,
      pval = NA
    )
    df_res <- rbind(df_res, missing_rows)
    df_res <- df_res[order(match(df_res$feature, feature_order)), ]
    rownames(df_res) <- as.character(seq_len(nrow(df_res)))
  }

  # Return results
  return(df_res)
}

#' Period of a GeneCycle spectrum index
#'
#' The rank-based spectrum of `GeneCycle::robust.spectrum()` is computed from
#' an autocorrelation zero-padded to twice the length of the time series, so
#' index k corresponds to `2 * n * delta_t / (k - 1)`. The regression-based
#' spectrum uses the standard Fourier frequencies, so index k corresponds to
#' `n * delta_t / (k - 1)`.
#'
#' @param index Integer vector of (1-based) spectrum indices.
#' @param n_rows Number of time points in the time series.
#' @param delta_t Sampling interval.
#' @param algorithm `"rank"` or `"regression"`.
#'
#' @returns A numeric vector of periods (`NA` for index 1, which is the mean,
#'   or if `delta_t` is unknown).
genecycle_index_period <- function(index, n_rows, delta_t, algorithm) {
  if (is.null(index) || length(index) == 0) {
    return(NA_real_)
  }
  index <- as.numeric(index)
  pad <- if (algorithm == "rank") 2 else 1
  period <- pad * n_rows * delta_t / (index - 1)
  period[!is.finite(period) | index <= 1] <- NA_real_
  period
}
